            self.wf(),
        ensures
            result.0 ==> result.1@.is_some(),
            result.0 ==> result.1@.unwrap().inv(
                self.flat_combiner_instance@,
                self.responses.id(),
                self.collected_operations.id(),
                self.collected_operations_per_thread.id(),
